import { HbrPlugin } from "../interfaces";

export default abstract class BasePlugin implements HbrPlugin.Plugin {
	private readonly subscriptions: Record<string, (e: CustomEvent) => void> = {};
	constructor(protected hbrtable: HTMLHbrTableElement) {}
	protected addEventListener(name: string, func: (e: CustomEvent) => void) {
		this.hbrtable.addEventListener(name, func);
		this.subscriptions[name] = func;
	}

	protected removeEventListener(type: string) {
		this.hbrtable.removeEventListener(type, this.subscriptions[type]);
		delete this.subscriptions[type];
	}

	protected emit(eventName: string, detail?: any) {
		const event = new CustomEvent(eventName, {
			detail: detail,
			cancelable: true,
		});
		this.hbrtable.dispatchEvent(event);
		return event;
	}

	protected clearSubscriptions() {
		for (const type in this.subscriptions) {
			this.removeEventListener(type);
		}
	}

	destroy() {
		this.clearSubscriptions();
	}
}
