import { HbrTableNS } from "../../interfaces";
import { ColumnCollection } from "../../services/column.data.provider";
import { ColumnItems } from "../../services/dimension.provider";
import { Group as StoreGroup } from "../../store/dataSource/data.store";
import BasePlugin from "../basePlugin";
interface Group extends StoreGroup {
  level: number;
}
export type ColumnGrouping = Record<HbrTableNS.DimensionCols, Group[]>;

export default class GroupingColumnPlugin extends BasePlugin {
  static gatherGroup<T extends ColumnCollection>(
    res: T,
    colData: HbrTableNS.ColumnGrouping,
    collection: T,
    level = 0
  ): T {
    // group template
    const group: Group = {
      ...colData,
      level,
      ids: [],
    };

    // check columns for update
    for (const k in collection.columns) {
      const key = k as keyof ColumnItems;
      const resultItem = res.columns[key];
      // [] to be type safe
      const collectionItem = collection.columns[key] || [];

      // if column data
      if (Array.isArray(resultItem) && Array.isArray(collectionItem)) {
        // fill columns
        resultItem.push(...collectionItem);

        // fill grouping
        if (collectionItem.length) {
          res.columnGrouping[key].push({
            ...group,
            ids: collectionItem.map((i) => i.prop),
          });
        }
      }
    }
    // merge column groupings
    for (const k in collection.columnGrouping) {
      const key = k as HbrTableNS.DimensionCols;
      const collectionItem = collection.columnGrouping[key];
      res.columnGrouping[key].push(...collectionItem);
    }
    res.maxLevel = Math.max(res.maxLevel, collection.maxLevel);
    return res;
  }

  static isColGrouping(
    colData: HbrTableNS.ColumnGrouping | HbrTableNS.ColumnRegular
  ): colData is HbrTableNS.ColumnGrouping {
    return !!(colData as HbrTableNS.ColumnGrouping).children;
  }
}
export function isColGrouping(
  colData: HbrTableNS.ColumnGrouping | HbrTableNS.ColumnRegular
): colData is HbrTableNS.ColumnGrouping {
  return !!(colData as HbrTableNS.ColumnGrouping).children;
}
